// Filter and Flag Rows: drops closed jobs, parses dates, flags rows for a human, and marks which jobs need the LLM.
// Mode: Run Once for All Items. Outputs one item per OPEN job.

const config = $('Validate Rules').first().json.config;
const norm = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
const HUMAN = 'Needs human decision';

// Stop if the CSV has no rows (the extract node sends one blank item when Always Output Data is on)
if ($input.all().every((i) => Object.keys(i.json).length === 0)) {
  throw new Error('CSV has no rows. Was the export empty?');
}

// Stop if the CSV is missing columns we rely on (e.g. a column was renamed in the CRM)
const REQUIRED = ['Job Number', 'Organization', 'Address', 'State', 'Sector', 'Status', 'Created Date', 'Label',
  'Repair Type Selected', 'Scheduling Timing', 'Scheduling Instructions', 'Job Instructions', 'Instructions from Inspector'];
const seenColumns = new Set($input.all().flatMap((i) => Object.keys(i.json)));
const missingColumns = REQUIRED.filter((c) => !seenColumns.has(c));
if (missingColumns.length) {
  throw new Error(`CSV is missing columns: ${missingColumns.join(', ')}. Was the export changed or a column renamed?`);
}

const STATE_NAMES = {
  'new south wales': 'NSW', 'australian capital territory': 'ACT', 'northern territory': 'NT',
  'western australia': 'WA', 'south australia': 'SA', victoria: 'VIC', queensland: 'QLD', tasmania: 'TAS',
  vic: 'VIC', nsw: 'NSW', qld: 'QLD', act: 'ACT', sa: 'SA', wa: 'WA', tas: 'TAS', nt: 'NT',
};

// The state written at the END of the address, or null if there isn't one.
// Street/suburb names like "Victoria Street" or "Victoria Point" are ignored because they aren't at the end.
function stateFromAddress(address) {
  let a = norm(address);
  if (!/(south|western) australia$/.test(a)) a = a.replace(/[\s,]*australia$/, '');
  a = a.replace(/[\s,]*\d{4}$/, '').replace(/[\s,.]+$/, '');
  for (const [name, code] of Object.entries(STATE_NAMES)) {
    if (a === name || a.endsWith(' ' + name) || a.endsWith(',' + name)) return code;
  }
  return null;
}

// "d/m/yyyy H:mm" -> { sort: "yyyy-mm-ddTHH:mm", display: "dd/mm/yyyy" }, or null if it doesn't fit exactly.
function parseCreated(text) {
  const m = String(text ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})$/);
  if (!m) return null;
  const [day, month, year, hour, minute] = m.slice(1).map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  if (d.getUTCDate() !== day || d.getUTCMonth() !== month - 1 || hour > 23 || minute > 59) return null;
  const p = (n) => String(n).padStart(2, '0');
  return { sort: `${year}-${p(month)}-${p(day)}T${p(hour)}:${p(minute)}`, display: `${p(day)}/${p(month)}/${year}` };
}

const NOTE_FIELDS = [
  ['Scheduling Timing', 'schedulingTiming'],
  ['Scheduling Instructions', 'schedulingInstructions'],
  ['Job Instructions', 'jobInstructions'],
  ['Instructions from Inspector', 'inspectorInstructions'],
];

const rows = $input.all().map((item, i) => ({ ...item.json, _csvRow: i + 2 }));
const openJobs = [];

for (const r of rows) {
  const status = norm(r['Status']);
  if (config.closedStatuses.includes(status)) continue; // counted in the Run Log as Closed Skipped

  const issues = [];
  const jobNumber = String(r['Job Number'] ?? '').trim();
  const state = String(r['State'] ?? '').trim().toUpperCase();
  const sector = norm(r['Sector']);

  if (!jobNumber) issues.push({ issue: 'Missing Job Number', sourceText: `CSV row ${r._csvRow}` });

  if (!config.openStatuses.includes(status)) {
    issues.push({ issue: `Unknown status "${r['Status']}" (not in Open or Closed status rules)`, sourceText: r['Status'] ?? '' });
  }

  const created = parseCreated(r['Created Date']);
  if (!created) issues.push({ issue: 'Created Date is not in d/m/yyyy H:mm format', sourceText: r['Created Date'] ?? '' });

  const addressState = stateFromAddress(r['Address']);
  if (addressState && addressState !== state) {
    issues.push({ issue: `State column says ${state} but address says ${addressState}`, sourceText: r['Address'] });
  }

  if (norm(r['Repair Type Selected']) === 'paid inspection') {
    issues.push({ issue: 'Paid inspection, not repair work', sourceText: r['Repair Type Selected'] });
  }

  const isEducation = config.educationSectors.includes(sector);
  if (isEducation && !config.schoolHolidays[state]) {
    issues.push({ issue: `Education job but no School holiday rows for state "${state}"`, sourceText: r['State'] ?? '' });
  }

  // Keep only notes with real content. A note that is exactly a no-constraint word counts as empty.
  const notes = {};
  const llmLines = [];
  for (const [column, key] of NOTE_FIELDS) {
    const raw = String(r[column] ?? '').trim();
    notes[key] = raw;
    if (raw && !config.noConstraintText.includes(norm(raw))) llmLines.push(`${column}: ${raw}`);
  }

  openJobs.push({
    jobNumber,
    csvRow: r._csvRow,
    organization: r['Organization'] ?? '',
    address: r['Address'] ?? '',
    state,
    sector: r['Sector'] ?? '',
    status: r['Status'] ?? '',
    repairType: r['Repair Type Selected'] ?? '',
    createdSort: created?.sort ?? null,
    createdDisplay: created?.display ?? String(r['Created Date'] ?? ''),
    isDirector: config.directorLabels.includes(norm(r['Label'])),
    isInProgress: config.inProgressStatuses.includes(status),
    isEducation,
    notes,
    llmText: llmLines.join('\n'),
    issues: issues.map((i) => ({ category: HUMAN, ...i })),
  });
}

// Duplicate Job Numbers among open jobs: flag every copy so none is silently overwritten later
const seen = {};
for (const j of openJobs) if (j.jobNumber) seen[j.jobNumber] = (seen[j.jobNumber] ?? 0) + 1;
for (const j of openJobs) {
  if (seen[j.jobNumber] > 1) j.issues.push({ category: HUMAN, issue: 'Duplicate Job Number', sourceText: j.jobNumber });
}

// Send to the LLM only if there is real text to read AND the job isn't already going to a human
for (const j of openJobs) j.needsLlm = j.llmText !== '' && j.issues.length === 0;

return openJobs.map((j) => ({ json: j }));

// Validate Rules: reads every Rules-tab row and turns them into ONE config item.
// If any rule is broken, it throws an error so the run stops before anything else happens.

const norm = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').toLowerCase();

const RANK_STEP_NAMES = ['director priority', 'education in holiday window', 'in progress'];
const LIST_RULES = {
  'director label': 'directorLabels',
  'in progress status': 'inProgressStatuses',
  'open status': 'openStatuses',
  'closed status': 'closedStatuses',
  'education sector': 'educationSectors',
  'no-constraint text': 'noConstraintText',
};
const DATE_RULES = ['planning window', 'school holiday', 'public holiday'];

// Sheets date (serial number, or "d/m/yyyy" text) -> "yyyy-mm-dd". Returns null if blank or invalid.
function toIsoDate(v) {
  const s = String(v ?? '').trim();
  if (s === '') return null;
  if (/^\d+(\.\d+)?$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(s)) * 86400000);
    return d.toISOString().slice(0, 10);
  }
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const day = Number(m[1]), month = Number(m[2]), year = Number(m[3]);
  const d = new Date(Date.UTC(year, month - 1, day));
  if (d.getUTCDate() !== day || d.getUTCMonth() !== month - 1) return null; // e.g. 31/02
  return d.toISOString().slice(0, 10);
}

const rows = $input.all().map((item, i) => ({ ...item.json, _row: item.json.row_number ?? i + 2 }));

if (!rows.some((r) => 'Rule' in r)) {
  throw new Error('Rules tab is empty, or row 1 is not the header: Rule | State | Value | From | To | Notes');
}

const config = {
  planningWindow: null,
  rankSteps: [],
  directorLabels: [], inProgressStatuses: [], openStatuses: [], closedStatuses: [],
  educationSectors: [], noConstraintText: [],
  schoolHolidays: {},  // { VIC: [{ term, from, to }], ... }
  publicHolidays: {},  // { NSW: [{ name, from, to }], ... }
};
const planningWindows = [];
const rankSteps = [];
const errors = [];

for (const r of rows) {
  const rule = norm(r.Rule);
  const value = norm(r.Value);
  const state = String(r.State ?? '').trim().toUpperCase();
  const fromText = String(r.From ?? '').trim();
  const toText = String(r.To ?? '').trim();
  const where = `Row ${r._row}`;

  // Skip completely blank rows
  if (!rule && !value && !state && !fromText && !toText) continue;

  // Check 1: unknown rule name
  const stepMatch = rule.match(/^rank step (\d+)$/);
  if (!LIST_RULES[rule] && !DATE_RULES.includes(rule) && !stepMatch) {
    errors.push(`${where}: unknown rule name "${r.Rule}"`);
    continue;
  }

  if (stepMatch) {
    if (RANK_STEP_NAMES.includes(value)) rankSteps.push({ order: Number(stepMatch[1]), name: value });
    else errors.push(`${where}: unknown rank step "${r.Value}" (use Director Priority, Education in holiday window, or In Progress)`);
    continue;
  }

  if (LIST_RULES[rule]) {
    if (value) config[LIST_RULES[rule]].push(value);
    continue;
  }

  // Check 2: missing date, or To before From
  const from = toIsoDate(r.From);
  const to = toIsoDate(r.To);
  const blankToAllowed = rule === 'school holiday' && toText === '';
  if (!from) { errors.push(`${where} (${r.Rule}): From date missing or not a valid date`); continue; }
  if (!to && !blankToAllowed) { errors.push(`${where} (${r.Rule}): To date missing or not a valid date`); continue; }
  if (to && to < from) { errors.push(`${where} (${r.Rule}): To ${to} is before From ${from}`); continue; }

  if (rule === 'planning window') planningWindows.push({ from, to });
  else if (rule === 'school holiday') (config.schoolHolidays[state] ??= []).push({ term: r.Value ?? '', from, to });
  else (config.publicHolidays[state] ??= []).push({ name: r.Value ?? '', from, to });
}

// Check 3: exactly one planning window
if (planningWindows.length === 0) errors.push('No "Planning window" row found');
if (planningWindows.length > 1) errors.push(`${planningWindows.length} "Planning window" rows found, keep only one`);

// Check 4: the same status in both Open and Closed
for (const s of config.openStatuses) {
  if (config.closedStatuses.includes(s)) errors.push(`Status "${s}" is listed as both Open and Closed`);
}

if (errors.length) {
  throw new Error(`Rules tab has ${errors.length} problem(s):\n- ${errors.join('\n- ')}`);
}

config.planningWindow = planningWindows[0];
config.rankSteps = rankSteps.sort((a, b) => a.order - b.order).map((s) => s.name);
for (const list of Object.values(config.schoolHolidays)) list.sort((a, b) => a.from.localeCompare(b.from));

return [{ json: { config, rulesRowCount: rows.length, startedAt: $now.toFormat('dd/MM/yyyy HH:mm:ss') } }];

// Merge LLM Results: joins each LLM extraction back to its job and checks it can be trusted.
// Mode: Run Once for All Items. Input: the LLM node's output. Output: ALL open jobs (62), each with llmStatus.

const config = $('Validate Rules').first().json.config;
const jobs = $('Filter and Flag Rows').all().map((i) => ({ ...i.json, issues: [...i.json.issues] }));
const HUMAN = 'Needs human decision';
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const defaultYear = Number(config.planningWindow.from.slice(0, 4));
const squash = (v) => String(v ?? '').toLowerCase().replace(/\s+/g, ' ').trim();

// 1. Collect LLM results by the job number the LLM echoed back
const results = {};
for (const item of $input.all()) {
  const out = item.json.output;
  if (!out || typeof out !== 'object') continue; // failed calls / empty items have no output
  const key = String(out.job_number ?? '').trim();
  (results[key] ??= []).push(out);
}

// LLM date -> "yyyy-mm-dd", or an error message
function resolveDate(d, label) {
  if (d === null || d === undefined) return { iso: null };
  if (typeof d !== 'object') return { error: `${label} is not a date object` };
  const day = d.day, month = d.month;
  const year = d.year ?? defaultYear;
  if (![day, month, year].every(Number.isInteger)) return { error: `${label} has a missing or non-whole day/month/year` };
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCDate() !== day || date.getUTCMonth() !== month - 1) return { error: `${label} ${day}/${month}/${year} is not a real date` };
  if (d.weekday && d.weekday !== WEEKDAYS[date.getUTCDay()]) {
    return { error: `${label} says ${d.weekday} but ${day}/${month}/${year} is a ${WEEKDAYS[date.getUTCDay()]}` };
  }
  return { iso: date.toISOString().slice(0, 10) };
}

// 2. Check one extraction. Returns { problems, extraction }
function check(out, job) {
  const problems = [];
  const text = squash(job.llmText);
  const quoteFound = (q) => typeof q === 'string' && q.trim() !== '' && text.includes(squash(q));

  const windows = [];
  if (!Array.isArray(out.date_windows)) problems.push('date_windows is not a list');
  for (const [n, w] of (Array.isArray(out.date_windows) ? out.date_windows : []).entries()) {
    const label = `window ${n + 1}`;
    if (!['allowed', 'avoid'].includes(w?.kind)) { problems.push(`${label} has kind "${w?.kind}"`); continue; }
    const start = resolveDate(w.start, `${label} start`);
    const end = resolveDate(w.end, `${label} end`);
    if (start.error) problems.push(start.error);
    if (end.error) problems.push(end.error);
    if (start.error || end.error) continue;
    if (!start.iso && !end.iso) { problems.push(`${label} has neither start nor end`); continue; }
    if (start.iso && end.iso && end.iso < start.iso) { problems.push(`${label} ends before it starts`); continue; }
    if (!quoteFound(w.source_quote)) { problems.push(`${label} quote not found in notes: "${w.source_quote}"`); continue; }
    windows.push({ kind: w.kind, start: start.iso, end: end.iso, quote: w.source_quote });
  }

  const weekdays = out.allowed_weekdays;
  if (weekdays !== null && weekdays !== undefined &&
      (!Array.isArray(weekdays) || weekdays.some((d) => !WEEKDAYS.includes(d)))) {
    problems.push(`allowed_weekdays is not a list of Mon..Sun: ${JSON.stringify(weekdays)}`);
  }
  for (const f of ['time_of_day', 'notice_required', 'unclear_timing']) {
    if (out[f] !== null && out[f] !== undefined && typeof out[f] !== 'string') problems.push(`${f} is not text`);
  }
  const preconditions = Array.isArray(out.preconditions) ? out.preconditions.filter((p) => String(p).trim()) : null;
  if (!preconditions) problems.push('preconditions is not a list');

  // Every quote must really be in the notes, and non-date answers need at least one quote
  const quotes = Array.isArray(out.source_quotes) ? out.source_quotes : [];
  for (const q of quotes) if (!quoteFound(q)) problems.push(`quote not found in notes: "${q}"`);
  const hasNonDateAnswer = (weekdays?.length > 0) || out.time_of_day || out.notice_required || out.unclear_timing || preconditions?.length > 0;
  if (hasNonDateAnswer && quotes.length === 0) problems.push('answers given without any source quote');

  return {
    problems,
    extraction: {
      dateWindows: windows,
      allowedWeekdays: weekdays?.length ? weekdays : null,
      timeOfDay: out.time_of_day || null,
      noticeRequired: out.notice_required || null,
      preconditions: preconditions ?? [],
      unclearTiming: out.unclear_timing || null,
      quotes,
    },
  };
}

// 3. Attach a result to every job that needed the LLM
for (const job of jobs) {
  job.extraction = null;
  if (!job.needsLlm) { job.llmStatus = 'skipped'; continue; }

  const found = results[job.jobNumber] ?? [];
  if (found.length === 0) {
    job.llmStatus = 'failed';
    job.issues.push({ category: HUMAN, issue: 'LLM extraction failed (no result after retries)', sourceText: job.llmText });
    continue;
  }
  if (found.length > 1) {
    job.llmStatus = 'invalid';
    job.issues.push({ category: HUMAN, issue: `LLM output invalid: ${found.length} results claim this job number`, sourceText: job.llmText });
    continue;
  }

  const { problems, extraction } = check(found[0], job);
  if (problems.length) {
    job.llmStatus = 'invalid';
    job.issues.push({ category: HUMAN, issue: `LLM output invalid: ${problems.join('; ')}`, sourceText: job.llmText });
  } else {
    job.llmStatus = 'ok';
    job.extraction = extraction;
  }
}

return jobs.map((j) => ({ json: j }));

// Categorise & Rank: decides Ranked vs Needs Review for every job, ranks the Ranked ones, and writes the reasons.
// Mode: Run Once for All Items. Input: 62 jobs from Merge LLM Results.
// Output: one item per job: { tab: 'Ranked' | 'Needs Review', row: { ...sheet columns } }

const config = $('Validate Rules').first().json.config;
const jobs = $input.all().map((i) => i.json);
const runId = `${$now.toFormat('yyyy-MM-dd HH:mm')} #${$execution.id}`;
const HUMAN = 'Needs human decision';
const LATER = 'Not this fortnight';
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const STEP_LABELS = {
  'director priority': 'Director Priority',
  'education in holiday window': 'Education in holiday window',
  'in progress': 'In Progress',
};
const LEFTOVER = 'Oldest first';

// ---------- date helpers (all dates are "yyyy-mm-dd" text) ----------
const toDate = (iso) => new Date(iso + 'T00:00:00Z');
const addDays = (iso, n) => new Date(toDate(iso).getTime() + n * 86400000).toISOString().slice(0, 10);
const weekday = (iso) => WEEKDAYS[toDate(iso).getUTCDay()];
const show = (iso) => `${iso.slice(8, 10)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}`;
const showShort = (iso) => `${weekday(iso)} ${iso.slice(8, 10)}/${iso.slice(5, 7)}`;
// Is the day inside a range? A null start or end means open-ended on that side.
const inRange = (iso, from, to) => (!from || iso >= from) && (!to || iso <= to);

const plan = config.planningWindow;
const planDays = [];
for (let d = plan.from; d <= plan.to; d = addDays(d, 1)) {
  if (!['Sat', 'Sun'].includes(weekday(d))) planDays.push(d); // crews work Mon-Fri
}

// Working days in the fortnight for one state (public holidays removed), plus the holidays that were removed
function stateDays(state) {
  const holidays = config.publicHolidays[state] ?? [];
  const removed = holidays.filter((h) => planDays.some((d) => inRange(d, h.from, h.to)));
  const days = planDays.filter((d) => !holidays.some((h) => inRange(d, h.from, h.to)));
  return { days, removed };
}

// "Any weekday 05/10–16/10", or ranges like "Tue 06/10–Fri 09/10"
function describeDays(days, allDays) {
  if (days.length === allDays.length) return `Any weekday ${show(days[0]).slice(0, 5)}–${show(days.at(-1)).slice(0, 5)}`;
  const groups = [];
  for (const d of days) {
    const last = groups.at(-1);
    if (last && planDays.indexOf(d) === planDays.indexOf(last.at(-1)) + 1) last.push(d);
    else groups.push([d]);
  }
  return groups.map((g) => (g.length === 1 ? showShort(g[0]) : `${showShort(g[0])}–${showShort(g.at(-1))}`)).join(', ');
}

// ---------- decide each job ----------
const ranked = [];
const review = [];

for (const job of jobs) {
  const issues = [...job.issues];
  const ex = job.extraction ?? { dateWindows: [], allowedWeekdays: null, preconditions: [], unclearTiming: null };
  const quotes = (ex.quotes ?? []).join(' | ');

  for (const p of ex.preconditions) issues.push({ category: HUMAN, issue: `Must happen before booking: ${p}`, sourceText: quotes });
  if (ex.unclearTiming) issues.push({ category: HUMAN, issue: `Timing can't be turned into dates: "${ex.unclearTiming}"`, sourceText: quotes });

  const { days: baseDays, removed } = stateDays(job.state);
  const allowed = ex.dateWindows.filter((w) => w.kind === 'allowed');
  const avoid = ex.dateWindows.filter((w) => w.kind === 'avoid');
  const holidays = job.isEducation ? (config.schoolHolidays[job.state] ?? []) : [];

  let days = baseDays;
  if (allowed.length) days = days.filter((d) => allowed.some((w) => inRange(d, w.start, w.end)));
  days = days.filter((d) => !avoid.some((w) => inRange(d, w.start, w.end)));
  if (ex.allowedWeekdays) days = days.filter((d) => ex.allowedWeekdays.includes(weekday(d)));
  if (job.isEducation) days = days.filter((d) => holidays.some((h) => inRange(d, h.from, h.to)));

  // No usable day this fortnight: is there a clear later date, or does a human need to look?
  if (days.length === 0 && !issues.some((i) => i.category === HUMAN)) {
    const after = addDays(plan.to, 1);
    const windowSource = allowed.map((w) => w.quote).join(' | ');
    const futureAllowed = allowed.filter((w) => !w.end || w.end >= after);

    if (allowed.length && futureAllowed.length === 0) {
      const lastEnd = allowed.map((w) => w.end).sort().at(-1);
      const why = lastEnd < plan.from
        ? `Client's date window has already passed (ended ${show(lastEnd)})`
        : `No weekday in the fortnight fits the client's dates${job.isEducation ? ` and ${job.state} school holidays` : ''} (client window ends ${show(lastEnd)})`;
      issues.push({ category: HUMAN, issue: why, sourceText: windowSource });
    } else if (job.isEducation) {
      const futureHols = holidays.filter((h) => !h.to || h.to >= after);
      // earliest day that is after the fortnight, inside a future holiday, and inside a future client window (if any)
      let earliest = null;
      for (const h of futureHols) {
        const ranges = futureAllowed.length ? futureAllowed : [{ start: null, end: null }];
        for (const w of ranges) {
          const start = [after, h.from, w.start].filter(Boolean).sort().at(-1);
          const end = [h.to, w.end].filter(Boolean).sort()[0] ?? null;
          if (!end || start <= end) earliest = earliest && earliest < start ? earliest : start;
        }
      }
      if (earliest) {
        issues.push({ category: LATER, issue: `No ${job.state} school holiday days in ${show(plan.from)}–${show(plan.to)}; next possible from ${show(earliest)}`, sourceText: windowSource || `${job.state} education job` });
      } else {
        issues.push({ category: HUMAN, issue: `Client's dates don't overlap any upcoming ${job.state} school holiday in the Rules tab`, sourceText: windowSource });
      }
    } else if (futureAllowed.length) {
      const earliest = futureAllowed.map((w) => w.start ?? after).map((s) => (s < after ? after : s)).sort()[0];
      issues.push({ category: LATER, issue: `Client's dates are after this fortnight; earliest ${show(earliest)}`, sourceText: windowSource });
    } else {
      issues.push({ category: HUMAN, issue: 'No weekday in the fortnight fits the notes (avoid dates / weekday limits)', sourceText: quotes });
    }
  }

  const base = {
    'Job Number': job.jobNumber,
    'Organization': job.organization,
    'State': job.state,
    'Sector': job.sector,
    'Status': job.status,
    'Created Date': job.createdDisplay,
  };

  if (issues.length) {
    const category = issues.some((i) => i.category === HUMAN) ? HUMAN : LATER;
    review.push({ job, row: {
      ...base,
      'Issue Category': category,
      'Issue': issues.map((i) => i.issue).join('; '),
      'Source Text': [...new Set(issues.map((i) => i.sourceText).filter(Boolean))].join(' | '),
      'Run ID': runId,
    } });
    continue;
  }

  // Rank step = the first step in Rules order that this job matches
  const matches = {
    'director priority': job.isDirector,
    'education in holiday window': job.isEducation,
    'in progress': job.isInProgress,
  };
  const stepIndex = config.rankSteps.findIndex((s) => matches[s]);
  const step = stepIndex === -1 ? LEFTOVER : STEP_LABELS[config.rankSteps[stepIndex]];

  const bookingNotes = [
    ex.timeOfDay,
    ex.noticeRequired,
    ex.allowedWeekdays ? `Only ${ex.allowedWeekdays.join(', ')}` : null,
  ].filter(Boolean).join('; ');

  ranked.push({
    job, days, removed, step, bookingNotes,
    group: stepIndex === -1 ? config.rankSteps.length : stepIndex,
    allowedDates: describeDays(days, planDays),
  });
}

// ---------- sort: rank step, then oldest Created Date, then Job Number ----------
const num = (s) => (/^\d+$/.test(s) ? Number(s) : Infinity);
ranked.sort((a, b) =>
  a.group - b.group ||
  a.job.createdSort.localeCompare(b.job.createdSort) ||
  num(a.job.jobNumber) - num(b.job.jobNumber) ||
  a.job.jobNumber.localeCompare(b.job.jobNumber));

// ---------- reasons ----------
const groupSize = {};
for (const r of ranked) groupSize[r.step] = (groupSize[r.step] ?? 0) + 1;
const seenInGroup = {};

const rankedRows = ranked.map((r, i) => {
  const pos = (seenInGroup[r.step] = (seenInGroup[r.step] ?? 0) + 1);
  const order = `${pos} of ${groupSize[r.step]} in this group by age (created ${r.job.createdDisplay})`;
  const holidayNote = r.removed.length ? ` (${r.removed.map((h) => `${show(h.from).slice(0, 5)} is ${h.name}`).join(', ')})` : '';
  let why;
  if (r.step === 'Director Priority') why = `Director Priority label; ${order}`;
  else if (r.step === 'Education in holiday window') why = `${r.job.state} education job inside school holidays: ${r.allowedDates}${holidayNote}; ${order}`;
  else if (r.step === 'In Progress') why = `Work already in progress; ${order}`;
  else why = `No higher rule applies; ${order}`;
  if (r.job.extraction?.noticeRequired) why += `; ${r.job.extraction.noticeRequired}`;

  return { tab: 'Ranked', row: {
    'Rank': i + 1,
    'Job Number': r.job.jobNumber,
    'Organization': r.job.organization,
    'State': r.job.state,
    'Sector': r.job.sector,
    'Status': r.job.status,
    'Created Date': r.job.createdDisplay,
    'Rank Step': r.step,
    'Allowed Dates': r.allowedDates + holidayNote,
    'Booking Notes': r.bookingNotes,
    'Reason': why,
    'Run ID': runId,
  } };
});

// Needs Review: human decisions first, then oldest first
review.sort((a, b) =>
  (a.row['Issue Category'] === HUMAN ? 0 : 1) - (b.row['Issue Category'] === HUMAN ? 0 : 1) ||
  String(a.job.createdSort).localeCompare(String(b.job.createdSort)));
const reviewRows = review.map((r) => ({ tab: 'Needs Review', row: r.row }));

return [...rankedRows, ...reviewRows].map((x) => ({ json: x }));

// Counts Check: proves every job is accounted for BEFORE anything is written. Throws (fails the run) if not.
// Mode: Run Once for All Items. Input: items from Categorise & Rank.
// Output: ONE item: { summary, ranked: [rows], review: [rows] }

const CSV_NODE = 'Checks backlog.csv';

const config = $('Validate Rules').first().json.config;
const norm = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').toLowerCase();

const csvRows = $(CSV_NODE).all().map((i) => i.json);
const openJobs = $('Filter and Flag Rows').all().map((i) => i.json);
const merged = $('Merge LLM Results').all().map((i) => i.json);
const out = $input.all().map((i) => i.json);

const ranked = out.filter((o) => o.tab === 'Ranked').map((o) => o.row);
const review = out.filter((o) => o.tab === 'Needs Review').map((o) => o.row);
const problems = [];

// 1. Every CSV row is either closed or open
const rowsRead = csvRows.length;
const closedSkipped = csvRows.filter((r) => config.closedStatuses.includes(norm(r['Status']))).length;
if (rowsRead === 0) problems.push('CSV has no rows');
if (closedSkipped + openJobs.length !== rowsRead) {
  problems.push(`Rows Read ${rowsRead} ≠ Closed ${closedSkipped} + Open ${openJobs.length}`);
}

// 2. Every open job lands in exactly one tab
if (out.some((o) => o.tab !== 'Ranked' && o.tab !== 'Needs Review')) problems.push('An output item has no valid tab');
if (ranked.length + review.length !== openJobs.length) {
  problems.push(`Ranked ${ranked.length} + Needs Review ${review.length} ≠ Open ${openJobs.length}`);
}

// 3. Same Job Numbers in as out (catches a job dropped and another duplicated, which plain totals would miss)
const tally = (list) => list.reduce((m, j) => m.set(j, (m.get(j) ?? 0) + 1), new Map());
const before = tally(openJobs.map((j) => j.jobNumber));
const after = tally([...ranked, ...review].map((r) => r['Job Number']));
for (const [job, n] of before) if (after.get(job) !== n) problems.push(`Job "${job}" appears ${after.get(job) ?? 0} time(s) in output, expected ${n}`);
for (const [job] of after) if (!before.has(job)) problems.push(`Job "${job}" is in the output but not in the open jobs`);

// 4. Ranks are 1..N with no gaps
const gap = ranked.findIndex((r, i) => r['Rank'] !== i + 1);
if (gap !== -1) problems.push(`Ranks are not 1..${ranked.length}: position ${gap + 1} has Rank ${ranked[gap]['Rank']}`);

// 5. Required cells are filled, and no broken values leaked into any cell
for (const r of ranked) if (!r['Reason'] || !r['Allowed Dates']) problems.push(`Ranked job ${r['Job Number']} is missing Reason or Allowed Dates`);
for (const r of review) {
  if (!['Needs human decision', 'Not this fortnight'].includes(r['Issue Category']) || !r['Issue']) {
    problems.push(`Needs Review job ${r['Job Number']} is missing a valid Issue Category or Issue`);
  }
}
const broken = /\bundefined\b|\bNaN\b|Invalid DateTime|\[object Object\]/;
for (const r of [...ranked, ...review]) {
  for (const [col, val] of Object.entries(r)) {
    if (broken.test(String(val))) problems.push(`Job ${r['Job Number']}, column "${col}" contains "${String(val).match(broken)[0]}"`);
  }
}
// 6. If too many AI calls failed, the AI itself is broken (outage, no balance, bad key, or a broken prompt).
//    Stop instead of sending every job to review and overwriting the good list.
const llmCalls = merged.filter((j) => j.needsLlm).length;
const llmNoResponse = merged.filter((j) => j.llmStatus === 'failed').length;
const llmBadOutput = merged.filter((j) => j.llmStatus === 'invalid').length;
const llmFailures = llmNoResponse + llmBadOutput;
const MAX_FAIL_SHARE = 0.2;
const MIN_FAILS_TO_STOP = 3;
if (llmFailures >= MIN_FAILS_TO_STOP && llmFailures / llmCalls > MAX_FAIL_SHARE) {
  problems.push(
    `${llmFailures} of ${llmCalls} AI calls failed (${llmNoResponse} no response, ${llmBadOutput} bad output). ` +
    (llmNoResponse >= llmBadOutput
      ? 'The AI service may be down, out of balance, or the key is wrong.'
      : 'Claude is answering but its output keeps failing checks: check the prompt or model.') +
    ' Old lists kept.'
  );
}

if (problems.length) {
  throw new Error(`Counts check failed, nothing was written:\n- ${problems.slice(0, 20).join('\n- ')}`);
}

const runId = (ranked[0] ?? review[0])?.['Run ID'] ?? `${$now.toFormat('yyyy-MM-dd HH:mm')} #${$execution.id}`;

return [{ json: {
  summary: {
    runId, rowsRead, closedSkipped, openJobs: openJobs.length,
    ranked: ranked.length, needsReview: review.length, llmCalls, llmFailures,
  },
  ranked,
  review,
} }];

// Ranked Rows: one item per Ranked sheet row
const { ranked, summary } = $('Counts Check').first().json;
if (ranked.length === 0) return [{ json: { 'Reason': `No jobs ranked in run ${summary.runId}`, 'Run ID': summary.runId } }];
return ranked.map((row) => ({ json: row }));

// Review Rows: one item per Needs Review sheet row
const { review, summary } = $('Counts Check').first().json;
if (review.length === 0) return [{ json: { 'Issue': `No jobs need review in run ${summary.runId}`, 'Run ID': summary.runId } }];
return review.map((row) => ({ json: row }));

// Run Log Row: builds the success row. Runs only after both tabs were written.
const s = $('Counts Check').first().json.summary;

return [{ json: {
  'Run ID': s.runId,
  'Started': $('Validate Rules').first().json.startedAt ?? '',
  'Finished': $now.toFormat('dd/MM/yyyy HH:mm:ss'),
  'Result': 'Success',
  'Rows Read': s.rowsRead,
  'Closed Skipped': s.closedSkipped,
  'Open Jobs': s.openJobs,
  'Ranked': s.ranked,
  'Needs Review': s.needsReview,
  'LLM Calls': s.llmCalls,
  'LLM Failures': s.llmFailures,
  'Error': '',
} }];
